// generated by gemini-3.5-flash-lite for PR #6077 (round 0): json_pointer_concatenation_operators
// intent: Exercise json_pointer division/concatenation operators with strings and indices.
#include <nlohmann/json.hpp>
#include <iostream>

int main() {
    try {
        nlohmann::json::json_pointer p("/foo");
        auto p_combined = p / "bar" / 0;
        std::cout << "combined pointer: " << p_combined.to_string() << std::endl;

        nlohmann::json::json_pointer p_other("/baz");
        auto p_sum = p_combined / p_other;
        std::cout << "sum pointer: " << p_sum.to_string() << std::endl;
    } catch (const std::exception& e) {
        std::cout << "exception: " << e.what() << std::endl;
    }
    return 0;
}
